local deferred = require "amf.script.sugar.deferred"
local LiteStartProcessor = require "amf.middleware.activity.processor.LiteStartProcessor"
local DownloadProcessor
if EnvUtil:isUnity() then
    DownloadProcessor = require "amf.middleware.activity.system.mini.DownloadProcessor"
elseif EnvUtil:isApp() then
    DownloadProcessor = require "amf.middleware.activity.processor.DownloadProcessor"
else
    DownloadProcessor = require "amf.middleware.activity.system.windows.DownloadProcessor"
end

local IconProcessor = require "amf.middleware.activity.processor.IconProcessor"
local LaunchProcessor = require "amf.middleware.activity.processor.LaunchProcessor"
local AutoPopupProcessor = require "amf.middleware.activity.processor.AutoPopupProcessor"

local ActivityEventCenter = require "amf.middleware.activity.event.ActivityEventCenter"
local ActivityMeta = require "amf.middleware.activity.config.ActivityMeta"
local ActivityDebugLog = require "amf.middleware.activity.debug.ActivityDebugLog"

local IActivity = require "amf.middleware.activity.node.IActivity"
local ActivityNode = class("ActivityNode").implement(IActivity)

function ActivityNode:ctor()
    self._state = ActivityConst.ActivityPeriod.END
    self._actMeta = ActivityMeta.new()

    self._configVersion = 0
    self._latestConfigVersion = 0

    self._actInfo = nil
    self._configAndActInfoSupported = nil

    self._processingCount = 0    

    self._launcherLoadSuccess = false
end

function ActivityNode:create(config, dirtyVersion, iconSystemReady, actInfo)
    local node = ActivityNode.new()
    if node:init(config, dirtyVersion, iconSystemReady, actInfo) then
        return node
    end
end

function ActivityNode:init(config, dirtyVersion, iconSystemReady, actInfo)
    self:refreshData(config, dirtyVersion, iconSystemReady, actInfo)
    if not self._actMeta:getVersion() then return end --fix: some act has no webgl1 version
    if self._state == ActivityConst.ActivityPeriod.END then return end

    self:initProcessorBefore()
    self:registerEvent()
    self:processing()

    return true
end

function ActivityNode:refreshData(config, dirtyVersion, iconSystemReady, actInfo)
    self._configAndActInfoSupported = nil
    self._configVersion = dirtyVersion
    self._iconSystemReady = iconSystemReady
    self._actInfo = actInfo
    self._actMeta:parseConfig(config)
    self:setIconSystemReady()
    self:updateState()
end

-- 活动node是否可以启动，需要在启动器下完之后才知道，即loadLauncher之后才知道是否可以
function ActivityNode:isEnabled()
    if not self._iconSystemReady then
        ActivityDebugLog:logWarning("iconSystemNotReady，暂不启动后续流程")
        return false
    end
    
    -- 活动启动器未加载，不能启动
    if not self._launcherLoadSuccess then
        ActivityDebugLog:logWarning(self._actMeta:getActSource() .. "启动器加载失败，isEnabled判定不过")
        return false
    end

    local config
    pcall(function()
        config = require("activity/" .. self._actMeta:getActSource())
    end)

    if not config then
        ActivityDebugLog:logWarning(self._actMeta:getActSource() .. "没有加载上config，无法启动")
        return false
    end

    return true
end

function ActivityNode:isConfigAndActInfoSupport()
    local config = require("activity/" .. self._actMeta:getActSource())
    local result
    if type(config) == "table" and config.isSupport then
        pcall(function(...)
            result = config.isSupport()
        end)
    end

    self._configAndActInfoSupported = result == true
    if not self._configAndActInfoSupported then
        return false
    end

    if self._actInfo and not self._actInfo.see then
        self._configAndActInfoSupported = false
        return false
    end

    return true
end

-- 返回最近一次活动启动阶段的 Config.isSupport 结果。
-- 未完成启动校验时返回 false，避免沿用本地缓存活动数据误触发强弹。
function ActivityNode:isConfigAndActInfoSupported()
    return self._configAndActInfoSupported == true
end

function ActivityNode:isActReady()
    if not self:isEnabled() then return false end
    return self._isActReady == true
end

function ActivityNode:update(config, dirtyVersion, iconSystemReady, actInfo)
    self:refreshData(config, dirtyVersion, iconSystemReady, actInfo)
    self:processing()
end

function ActivityNode:setIconSystemReady()
    if self.iconProcessor then
        self.iconProcessor:setIconSystemReady(self._iconSystemReady)
    end
end

function ActivityNode:initProcessorBefore()
    local source = self._actMeta:getActSource()
    local actId = self._actMeta:getActId()
    self.downloadProcessor = DownloadProcessor:create(source, actId)
end

function ActivityNode:initProcessorAfter()
    if self.iconProcessor then
        self:setIconSystemReady()
        return
    end
    local source = self._actMeta:getActSource()
    local actId = self._actMeta:getActId()
    self.iconProcessor = IconProcessor:create(source, actId)
    self.liteStartProcessor = LiteStartProcessor:create(source, actId)
    self.autoPopupProcessor = AutoPopupProcessor:create(source, actId)
    self.launchProcessor = LaunchProcessor:create(source, actId)
    self:setIconSystemReady()
end

function ActivityNode:setLatestConfigVersion(v)
    self._latestConfigVersion = v
end

function ActivityNode:isInvalid()
    return self._state == ActivityConst.ActivityPeriod.END or self._configVersion < self._latestConfigVersion
end

function ActivityNode:isResLoaded()
    return self._isResLoaded
end

function ActivityNode:updateState()
    local actPeriod
    local nowTime = TimeKit:timeInSec()
    if nowTime < self._actMeta:getBeginTime() then
        actPeriod = ActivityConst.ActivityPeriod.BEFORE_BEGIN
    elseif nowTime < self._actMeta:getMainBeginTime() then
        actPeriod = ActivityConst.ActivityPeriod.PREHEAT
    elseif nowTime < self._actMeta:getMainEndTime() then
        actPeriod = ActivityConst.ActivityPeriod.MAIN
    elseif nowTime < self._actMeta:getEndTime() then
        actPeriod = ActivityConst.ActivityPeriod.AWARD
    else
        actPeriod = ActivityConst.ActivityPeriod.END
    end

    self._oldState = self._state
    self._state = actPeriod

    -- if self._oldState ~= self._state then
    --     ActivityEventCenter:dispatch(ActivityEvent.ACTIVITY_PERIOD_CHANGE, {
    --         actId = self._actMeta:getActId(),
    --         oldState = self._oldState,
    --         newState = self._state
    --     })
    -- end
end

function ActivityNode:registerEvent()
    self.onActInfoUpdate = function(event)
        local data = event:getData()
        local actInfos = data.actInfos
        local actInfo = actInfos[tostring(self._actMeta:getActId())]
        self:updateActInfo(actInfo)
    end

    ActivityEventCenter:register(ActivityEvent.ACT_INFOS_UPDATE, self.onActInfoUpdate)
end

function ActivityNode:unregisterEvent()
    ActivityEventCenter:unregister(ActivityEvent.ACT_INFOS_UPDATE, self.onActInfoUpdate)
end

function ActivityNode:updateActInfo(actInfo)
    if not actInfo then
        return
    end

    ActivityDebugLog:log("更新actInfo", self._actMeta:getActId())

    self._actInfo = actInfo
    
    self:updateState()
    self:afterLauncher(self._configVersion)
end

function ActivityNode:getActInfo()
    return self._actInfo
end

function ActivityNode:getAutoPopupData(delegate)
    if self.autoPopupProcessor then
        local data = self.autoPopupProcessor:getAutoPopupData(delegate)
        if self._isResLoaded then
            return data
        end
    end
end

function ActivityNode:checkHasAutoPopupByMetaId(metaId)
    if self.autoPopupProcessor then
        return self.autoPopupProcessor:checkHasAutoPopupByMetaId(metaId)
    end
end

function ActivityNode:onActivityPopupOver(data)
    if self.autoPopupProcessor then
        self.autoPopupProcessor:popupOverFunc(data)
    end
end

function ActivityNode:processOver(result, configVersion)
    if self:isProcessing() then
        return
    end
    self._isActReady = result
    ActivityEventCenter:dispatch(ActivityEvent.ACTIVITY_RESOLVE_OVER, {
        actId = self._actMeta:getActId(),
        configVersion = configVersion or self._configVersion,
        result = result,
        activityNode = self,
    })
end

function ActivityNode:setProcessing()
    self._processingCount = self._processingCount + 1
end

function ActivityNode:finishProcessing()
    self._processingCount = self._processingCount - 1
end

function ActivityNode:isProcessing()
    return self._processingCount > 0
end

-- 流程 启动器下载后判断活动是否可以开启，开启的话去创建icon并发liteStart，但loadLauncher和后面两步本身可以剥离，无关
function ActivityNode:processing()
    self:setProcessing()
    local configVersion = self._configVersion
    if not EnvUtil:isWindows() and self._launcherLoadSuccess then
        self:afterLauncher(configVersion, function()
            self:finishProcessing()
        end)
        return
    end
    self:loadLauncher():next(function()
        self._launcherLoadSuccess = true
        self:afterLauncher(configVersion, function()
            self:finishProcessing()
        end)
    end,function()
        ActivityDebugLog:logWarning("启动器加载失败" .. self._actMeta:getActId() .. "活动无法启动")
        self:processOver(false, configVersion)
        self:finishProcessing()
    end)
end

function ActivityNode:pushDataIntoConfig()
    local config = require("activity/" .. self._actMeta:getActSource())
    config.setAttributes({
        beginTime = self._actMeta:getBeginTime(),
        endTime = self._actMeta:getEndTime(),
        mainBeginTime = self._actMeta:getMainBeginTime(),
        mainEndTime = self._actMeta:getMainEndTime(),
        actInfo = self._actInfo
    })
end

function ActivityNode:loadLauncher()
    ActivityDebugLog:log("加载器下载",self._actMeta:getActId())
    local version = self._actMeta:getVersion()
    return self.downloadProcessor:process(version, ActivityConst.DownloadType.LAUNCHER)
end

function ActivityNode:loadLauncherMain()
    return self.downloadProcessor:loadLauncherMain(self._actMeta:getActSource())
end

function ActivityNode:loadIconRes()
    ActivityDebugLog:log("icon下载",self._actMeta:getActId())
    local version = self._actMeta:getVersion()
    return self.downloadProcessor:process(version, ActivityConst.DownloadType.ICON)
end

function ActivityNode:loadCode()
    ActivityDebugLog:log("代码下载",self._actMeta:getActId())
    local version = self._actMeta:getVersion()
    return self.downloadProcessor:process(version, ActivityConst.DownloadType.CODE)
end

function ActivityNode:loadRes(silent)
    ActivityDebugLog:log("全部资源下载",self._actMeta:getActId())
    local version = self._actMeta:getVersion()
    return self.downloadProcessor:process(version, ActivityConst.DownloadType.COMPLETE, silent)
end

function ActivityNode:loadCodeAndIcon()
    local d = deferred.new()
    if self._codeAndIconFinish then
        d:resolve()
        return d
    end

    self:loadIconRes():next(function()
        return self:loadCode()
    end):next(function()
        self._codeAndIconFinish = true
        d:resolve()
    end, function()
        d:reject()
    end)

    return d
end

function ActivityNode:loadActFail(msg, configVersion)
    ActivityDebugLog:logWarning(msg, self._actMeta:getActId())
    self:unloadProcessorAfter()
    self:processOver(false, configVersion)
end

function ActivityNode:afterLauncher(configVersion, callback)
    -- 资源没下完，或者没config，活动不启动
    if not self:isEnabled() then
        safeRunCall(callback)
        self:loadActFail("活动not enabled, 不能启动 ", configVersion)
        return
    end

    self:pushDataIntoConfig()

    -- config.isSupport没过或者actInfo没过，活动不启动
    if not self:isConfigAndActInfoSupport() then
        safeRunCall(callback)
        self:loadActFail("活动not isSupport, 不能启动 ", configVersion)
        return
    end
    
    self:loadLauncherMain():next(function()
        return self:loadCodeAndIcon()
    end):next(function()
        self:initProcessorAfter()
        self:handleIcon()
        self:handleLiteStart()
        self:handleAutoPopup()

        safeRunCall(callback)
        if self.iconProcessor then
            self:processOver(true, configVersion)
        else
            self:processOver(false, configVersion)
        end
    end, function()
        safeRunCall(callback)
        self:loadActFail("活动icon或代码加载失败, 不能启动", configVersion)
    end)
end

function ActivityNode:tryReleaseDownloadProcessor()
    if self.downloadProcessor then
        self.downloadProcessor:dispose()
        self.downloadProcessor = nil
    end
end

function ActivityNode:tryReleaseIconProcessor()
    if self.iconProcessor then
        local disposed, disposeError = self.iconProcessor:dispose()
        if disposed == false then
            return false, disposeError
        end
        self.iconProcessor = nil
    end
    return true
end

function ActivityNode:tryReleaseLiteProcessor()
    if self.liteStartProcessor then
        self.liteStartProcessor:dispose()
        self.liteStartProcessor = nil
    end
end

function ActivityNode:tryReleaseAutoPopupProcessor()
    if self.autoPopupProcessor then
        self.autoPopupProcessor:dispose()
        self.autoPopupProcessor = nil
    end
end

function ActivityNode:tryReleaseLaunchProcessor()
    if self.launchProcessor then
        self.launchProcessor:dispose()
        self.launchProcessor = nil
    end
end

function ActivityNode:unloadProcessorBefore()
    self:tryReleaseDownloadProcessor()
end

function ActivityNode:unloadProcessorAfter()
    local iconReleased, iconReleaseError = self:tryReleaseIconProcessor()
    self:tryReleaseLiteProcessor()
    self:tryReleaseAutoPopupProcessor()
    self:tryReleaseLaunchProcessor()
    return iconReleased, iconReleaseError
end

function ActivityNode:handleIcon()
    if not self.iconProcessor then return end
    self.iconProcessor:setPopTimeEnabled(self._state == ActivityConst.ActivityPeriod.MAIN
        or self._state == ActivityConst.ActivityPeriod.PREHEAT)
    self.iconProcessor:process(self._actInfo)
end

-- 重建icon
function ActivityNode:rebuildIcon()
    if not self._codeAndIconFinish then return end
    
    if self.iconProcessor then
        self.iconProcessor:rebuildIcon(self._actInfo)
    end
end

function ActivityNode:handleLiteStart()
    if not self.liteStartProcessor then return end
    -- liteStart重发
    self.liteStartProcessor:setReLiteFlag(self._state == ActivityConst.ActivityPeriod.MAIN and self._oldState ~=
                                              self._state)
    return self.liteStartProcessor:process()
end

function ActivityNode:handleAutoPopup()
    if not self.autoPopupProcessor then return end
    if self._oldState ~= self._state then
        self.autoPopupProcessor:setEventHandled(false)
    end
    local result = self.autoPopupProcessor:process()
    -- 有强弹，静默下载资源
    if result then
        self:downloadResSilent()
    end
end

function ActivityNode:openActivity(delegate)
    if not delegate then
        delegate = {}
    end

    if self._isResLoading then
        ActivityDebugLog:logWarning("资源加载中，稍后再点" .. self._actMeta:getActId())
        safeRunCall(delegate.failCallback)
        return
    end

    if self:isEnabled() and self:isConfigAndActInfoSupport() then
        if not EnvUtil:isWindows() and self._isResLoaded then
            self:pushDataIntoConfig()
            self:loadCodeAndIcon():next(function()
                self:initProcessorAfter()
                self:beforeLaunch(delegate)
                self.launchProcessor:process(delegate)
            end,function()
                safeRunCall(delegate.failCallback)
            end)
            return
        end

        self._isResLoading = true
        self._isResLoaded = false
        self:loadCodeAndIcon():next(function()
            self:initProcessorAfter()
            return self:loadRes()
        end):next(function()
            --资源重新加载会导致config所需数据消失，需要重新push，目前windows特供
            self:pushDataIntoConfig()
            self._isResLoaded = true
            self._isResLoading = false
            if self.launchProcessor then
                self:beforeLaunch(delegate)
                self.launchProcessor:process(delegate)
            else
                safeRunCall(delegate.failCallback)
                ActivityDebugLog:logError("活动" .. self._actMeta:getActId() .. "launcher被释放，无法打开")
            end
        end, function()
            ActivityDebugLog:logWarning("活动" .. self._actMeta:getActId() .. "完整资源下载失败, 无法开启后续流程")
            self._isResLoaded = false
            self._isResLoading = false
            safeRunCall(delegate.failCallback)
        end)
    else
        ActivityDebugLog:logWarning("活动" .. self._actMeta:getActId() .. "不满足条件，不能开启")
        safeRunCall(delegate.failCallback)
    end
end

function ActivityNode:downloadResSilent()
    if self._isResLoaded then return end
    if self:isEnabled() and self:isConfigAndActInfoSupport() then
        self:loadRes(true):next(function()
            --资源重新加载会导致config所需数据消失，需要重新push，目前windows特供
            self:pushDataIntoConfig()
            self._isResLoaded = true
        end, function()
            ActivityDebugLog:logWarning("活动" .. self._actMeta:getActId() .. "完整资源下载失败, 无法开启后续流程")
            self._isResLoaded = false
        end)
    end
end

function ActivityNode:beforeLaunch(delegate)
    local token = delegate and delegate.iconClickLockToken
    if token then
        ActivityEventCenter:dispatch(ActivityEvent.ACTIVITY_OPEN_HANDOFF, {
            actId = self._actMeta:getActId(),
            token = token,
        })
    end
end

function ActivityNode:getConfig()
    if self._launcherLoadSuccess then
        return require("activity/" .. self._actMeta:getActSource())
    end
end

--暂时不用，downloadProcessor保留，后续重新update会重启
function ActivityNode:tmpUnUse()
    return self:unloadProcessorAfter()
end

-- 释放
function ActivityNode:dispose()
    -- icon释放，所有事件注销
    self:unregisterEvent()
    self:unloadProcessorBefore()
    return self:unloadProcessorAfter()
end

return ActivityNode
